-- The design record (D128-D131; spec #168, ticket #170).
-- Generated by drizzle-kit (the `events` changes), then the backfill added by hand. One transaction:
--   1. `events` may record a venue's design: the op `setDesign`, with no node (only that op has
--      none) and always the venue's scope, the key `design` and the manual layer. The purge finds
--      those rows by their scope, as it finds every venue-scoped row;
--   2. every venue gets its design record at `settings.design` (core's `DesignRecordSchema`), on
--      Basic, revision 1, written by `system` under the job `migration:0043_design_record`, with
--      what it set before carried over:
--        - its three colours (or the one brand colour of a venue that never set three), its
--          Advanced role overrides and its logo, as they were;
--        - its font as the body font (the heading font stays Basic's `same`);
--        - its corner radius as the nearest Corners word (square 0, soft 8, round 16, extra 24 px;
--          a tie goes to the rounder) and its shadow as the nearest Depth word (none 0, low 1);
--        - its light/dark policy as the Screen;
--        - the layout and guest switch of its live menu as Layout and Guest switch (two columns
--          and on when the menu never set them: the look it has today);
--      and `settings.theme` and `settings.presentation` go: the record replaces them (D129). No
--      venue is moved onto Editorial (D128). The menus' own settings are left as they are;
--   3. back to normal.
-- `venues` and `menus` stop forcing row-level security on their owner for the length of the
-- backfill (packages/db/CLAUDE.md, as 0019 does) and `venues` stops touching `updated_at`: the
-- backfill must see every row and change nothing else. Runs on staging only with Martin's OK.

-- 1. The changelog records a venue's design.
ALTER TABLE "restro"."events" DROP CONSTRAINT "events_op";--> statement-breakpoint
ALTER TABLE "restro"."events" ALTER COLUMN "node_id" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."events" ADD CONSTRAINT "events_node_only_for_document_ops" CHECK (("restro"."events"."op" = 'setDesign') = ("restro"."events"."node_id" is null));--> statement-breakpoint
ALTER TABLE "restro"."events" ADD CONSTRAINT "events_design_scope" CHECK ("restro"."events"."op" <> 'setDesign' or ("restro"."events"."scope" ~ '^venue:vn_[0-9A-Za-z]+$' and "restro"."events"."field_key" = 'design' and "restro"."events"."layer" = 'manual'));--> statement-breakpoint
ALTER TABLE "restro"."events" ADD CONSTRAINT "events_op" CHECK ("restro"."events"."op" in ('setField', 'clearField', 'createNode', 'setPlacement', 'removePlacement', 'moveNode', 'setNodeStatus', 'linkSource', 'unlinkSource', 'setLinkState', 'setDesign'));--> statement-breakpoint

-- 2. Every venue's design record, from what it set before. Owner access first; undone at step 3.
ALTER TABLE "restro"."venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."menus" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" DISABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint
WITH old AS (
  SELECT
    v.id,
    CASE WHEN jsonb_typeof(v.settings -> 'theme') = 'object' THEN v.settings -> 'theme' ELSE '{}'::jsonb END AS theme,
    coalesce((SELECT m.settings FROM restro.menus m WHERE m.id = v.live_menu_id), '{}'::jsonb) AS menu
  FROM restro.venues v
  WHERE NOT (v.settings ? 'design')
),
mapped AS (
  SELECT
    id,
    CASE
      WHEN theme ->> 'font' IN ('inter', 'manrope', 'montserrat', 'playfair-display', 'lora', 'unbounded')
        THEN theme ->> 'font'
      ELSE 'inter'
    END AS body_font,
    CASE
      WHEN jsonb_typeof(theme -> 'radius') IS DISTINCT FROM 'number' THEN 'soft'
      WHEN (theme ->> 'radius')::numeric < 4 THEN 'square'
      WHEN (theme ->> 'radius')::numeric < 12 THEN 'soft'
      WHEN (theme ->> 'radius')::numeric < 20 THEN 'round'
      ELSE 'extra'
    END AS corners,
    CASE
      WHEN jsonb_typeof(theme -> 'shadow') = 'number' AND (theme ->> 'shadow')::numeric < 0.5 THEN 'none'
      ELSE 'low'
    END AS depth,
    CASE WHEN theme ->> 'scheme' IN ('auto', 'light', 'dark') THEN theme ->> 'scheme' ELSE 'auto' END AS screen,
    CASE menu ->> 'layout' WHEN 'list' THEN 'list' WHEN 'one_column' THEN 'one' ELSE 'two' END AS layout,
    CASE WHEN menu -> 'layout_switch' = 'false'::jsonb THEN 'off' ELSE 'on' END AS guest_switch,
    CASE
      WHEN jsonb_typeof(theme -> 'colors') = 'object'
        AND theme -> 'colors' ->> 'primary' ~* '^#[0-9a-f]{6}$'
        AND theme -> 'colors' ->> 'secondary' ~* '^#[0-9a-f]{6}$'
        AND theme -> 'colors' ->> 'tertiary' ~* '^#[0-9a-f]{6}$'
        THEN jsonb_build_object(
          'primary', lower(theme -> 'colors' ->> 'primary'),
          'secondary', lower(theme -> 'colors' ->> 'secondary'),
          'tertiary', lower(theme -> 'colors' ->> 'tertiary'))
    END AS colors,
    CASE WHEN theme ->> 'brand' ~* '^#[0-9a-f]{6}$' THEN lower(theme ->> 'brand') END AS brand,
    CASE WHEN jsonb_typeof(theme -> 'overrides') = 'object' THEN theme -> 'overrides' END AS overrides,
    CASE WHEN theme ->> 'logo_asset_id' ~ '^as_[0-9A-Za-z]{22}$' THEN theme ->> 'logo_asset_id' END AS logo
  FROM old
),
records AS (
  SELECT
    id,
    jsonb_build_object(
      'revision', 1,
      'style', 'basic',
      'values',
      -- Basic's values (the first of every row of the contract, D130), with the carried ones set.
      jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(
        '{"general":{"screen":"auto","body_font":"inter","heading_font":"same","heading_weight":"bold","corners":"soft","depth":"low","density":"comfortable","text_size":"standard","buttons":"accent"},"header":{"band":"page","arrangement":"stacked","title_size":"m","logo_size":"m"},"navigation":{"marker":"underline","band":"page"},"sections":{"header":"ruled","title_size":"m","title_case":"written","strip_card_size":"m"},"items":{"frame":"rows","name_size":"m","name_weight":"bold","name_case":"written","price_place":"end","portion_place":"beside","description_lines":"2","layout":"list","guest_switch":"on"},"photos":{"shape":"landscape","fit":"cover","backdrop":"panel","frame":"bleed","corners":"general"},"labels":{"labels":"outline","allergens":"numbers"},"dish":{"kind":"sheet","photo":"hero"},"sheets":{"sheets":"panel"},"call":{"kinds":"tiles"},"bill":{"rows":"ruled","lines":"detailed"},"order":{"add_control":"plus","order_bar":"floating","line_photos":"hidden"},"pay":{"tip":"chips"},"receipt":{"venue_block":"name"}}'::jsonb,
        '{general,screen}', to_jsonb(screen)),
        '{general,body_font}', to_jsonb(body_font)),
        '{general,corners}', to_jsonb(corners)),
        '{general,depth}', to_jsonb(depth)),
        '{items,layout}', to_jsonb(layout)),
        '{items,guest_switch}', to_jsonb(guest_switch)),
        '{general,heading_font}', '"same"'::jsonb),
      'logo_asset_id', to_jsonb(logo),
      'provenance', jsonb_build_object(
        'layer', 'manual',
        'source', 'manual',
        'actor', 'system',
        'job_id', 'migration:0043_design_record',
        'change_set_id', NULL))
    -- The three colours win over a brand colour, as they did at publish (`themePaletteOf`).
    || CASE WHEN colors IS NOT NULL THEN jsonb_build_object('colors', colors)
            WHEN brand IS NOT NULL THEN jsonb_build_object('brand', brand)
            ELSE '{}'::jsonb END
    || CASE WHEN overrides IS NOT NULL THEN jsonb_build_object('overrides', overrides) ELSE '{}'::jsonb END
      AS record
  FROM mapped
)
UPDATE "restro"."venues" v
SET settings = (v.settings - 'theme' - 'presentation') || jsonb_build_object('design', r.record)
FROM records r
WHERE v.id = r.id;--> statement-breakpoint

-- 3. Back to normal.
ALTER TABLE "restro"."venues" ENABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."menus" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" FORCE ROW LEVEL SECURITY;
